import json,sys
d=json.load(sys.stdin)
items=d['items']
print('WARNINGS:',json.dumps(d['warnings'],indent=1))
kids={}
by={}
for i in items:
    by[i['id']]=i
    p=i.get('parent')
    if p: kids.setdefault(p,[]).append(i['id'])
closed={'done','rejected','cancelled'}
for pid,ks in sorted(kids.items()):
    p=by.get(pid)
    if not p: print('ORPHAN parent ref',pid); continue
    st=[by[k]['status'] for k in ks]
    if p['status'] not in closed and all(s=='done' for s in st):
        print('ALL-CHILDREN-DONE, parent open:',pid,p['status'],len(ks))
    if p['status']=='done' and any(s not in closed for s in st):
        print('DONE parent w/ open children:',pid,[ (k,by[k]['status']) for k in ks if by[k]['status'] not in closed])
"

